window.__PAGES=window.__PAGES||{};window.__PAGES["pages/notification.html"]="<!-- Notification Page -->\n<style>\n.notif-list{display:flex;flex-direction:column;gap:2px}\n.notif-item{display:flex;align-items:flex-start;gap:12px;padding:12px 16px;cursor:pointer;border-radius:8px;transition:.1s}\n.notif-item:hover{background:var(--bg)}\n.notif-item.unread{background:rgba(79,70,229,.04);border-left:3px solid var(--accent)}\n.notif-icon{width:36px;height:36px;border-radius:50%;display:grid;place-items:center;font-size:16px;flex:0 0 36px}\n.notif-body{flex:1;min-width:0}\n.notif-title{font-size:13px;font-weight:600}.notif-text{font-size:12px;color:var(--muted);margin-top:2px}\n.notif-time{font-size:11px;color:var(--muted);flex:0 0 auto;margin-top:2px}\n.notif-actions{display:flex;gap:8px;padding:8px 0;border-bottom:1px solid var(--border);margin-bottom:8px}\n</style>\n\n<div class=\"page-header\">\n  <h1>🔔 Notifikasi</h1>\n  <button class=\"btn\" onclick=\"markAllRead()\">Tandai Semua Dibaca</button>\n</div>\n<div class=\"page-filters\">\n  <span class=\"filter-chip active\" onclick=\"filterNotif(this,'all')\">Semua</span>\n  <span class=\"filter-chip\" onclick=\"filterNotif(this,'unread')\">Belum Dibaca</span>\n</div>\n<div class=\"page-body\">\n  <div class=\"notif-list\" id=\"notifList\"></div>\n</div>\n\n<script>\nlet notifFilter='all';\nconst ICONS={message:'💬',ticket:'🎫',broadcast:'📣',assignment:'👤',lead:'📋'};\n\nfunction renderNotifs(){\n  const el=document.getElementById('notifList');\n  let items=DB.notifications.filter(n=>notifFilter==='all'||!n.read);\n  items.sort((a,b)=>new Date(b.time)-new Date(a.time));\n  el.innerHTML=items.map(n=>`<div class=\"notif-item ${n.read?'':'unread'}\" onclick=\"readNotif('${n.id}','${n.link||''}')\">\n    <div class=\"notif-icon\" style=\"background:var(--bg)\">${ICONS[n.type]||'🔔'}</div>\n    <div class=\"notif-body\"><div class=\"notif-title\">${n.title}</div><div class=\"notif-text\">${n.body}</div></div>\n    <div class=\"notif-time\">${fmtTime(n.time)}</div>\n  </div>`).join('')||'<div style=\"text-align:center;color:var(--muted);padding:40px\">Tidak ada notifikasi</div>';\n}\n\nfunction filterNotif(el,f){\n  document.querySelectorAll('.page-filters .filter-chip').forEach(c=>c.classList.remove('active'));\n  el.classList.add('active');notifFilter=f;renderNotifs();\n}\n\nfunction readNotif(id,link){\n  dbUpdate('notifications',id,{read:true});\n  if(link)go(link);else renderNotifs();\n}\n\nfunction markAllRead(){\n  DB.notifications.forEach(n=>n.read=true);saveStore();renderNotifs();showToast('Semua notifikasi ditandai dibaca');\n}\n\nrenderNotifs();\n</script>\n";
